  '5c527ad1-298d-4785-8d74-8ae87397a90d', 'Parte 1 · Avisos y letreros',
  'Where can you see this notice?',
  array['in a computer shop', 'in a music shop', 'in a bookshop'],
  'Busca el sustantivo clave del aviso (aquí, guitars) y pregúntate qué negocio vende justo eso.', 'publicada', 'modelo', '7ad1938166cf230254f963b4e390e6f4';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f3f9cf15-2ab6-4511-bfa3-defe50401043', 1, '«Guitars» son guitarras, así que el aviso invita a probar instrumentos: solo tiene sentido en una tienda de música. Las otras dos tiendas venden computadores y libros, que no se «prueban» tocando.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '45c19c09-6b9f-44d2-8d86-9162f82846be', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-1-avisos'),
