  'aacebde1-8111-4e58-a379-57de7a4161ca', 'Parte 1 · Avisos y letreros',
  'Where can you see this notice?',
  array['in a department store', 'outside an apartment', 'in a bank'],
  'Cuando un aviso menciona un piso o una sección, piensa en un edificio con varias áreas de venta.', 'publicada', 'modelo', '306a47c59ec0f6fad27299fe6bf1a939';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('45c19c09-6b9f-44d2-8d86-9162f82846be', 0, 'La pista está en «3rd floor»: solo un almacén grande con varios pisos necesita indicarte en cuál está la sección de música. Un apartamento no tiene secciones y un banco no vende música.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'c214fe9d-b1e9-43d4-9f75-73696d540168', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-1-avisos'),
  (select id from public.lotes where codigo = '2026-B'),
  '8ff1ba77-d9f5-4ba8-8f92-659a4f3e32c9', 'Parte 1 · Avisos y letreros',
  'Where can you see this notice?',
  array['at a theatre', 'at a train station', 'at a cinema'],
  'En inglés británico, single = solo ida y return = ida y vuelta. Ese par apunta siempre a transporte.', 'publicada', 'modelo', 'aec848c0ac976a168871d8dcb34b4778';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c214fe9d-b1e9-43d4-9f75-73696d540168', 1, 'La clave es «return ticket», el tiquete de ida y vuelta. Al teatro y al cine se compra una sola entrada para la función; nadie compra «ida y vuelta» para ver una película. Ese par «single / return» es de transporte.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
