insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ac34cc63-8fbf-4e1c-a2cd-ba3c60c34bdd', 0, 'El aviso habla de una norma dentro de un bote («in the boat»), y los botes están donde hay agua: junto al lago. Una zapatería vende zapatos, no exige usarlos, y en una finca no hay botes.');

