insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1f9be17a-8dfc-40f7-9bef-dfcfae84fadf', 1, '«Exam» y «room 3C» son vocabulario de salones numerados: se presenta un examen, y eso ocurre en un colegio. En una iglesia también se pide silencio, pero no se hacen exámenes en aulas numeradas.');

