insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f309c2a4-9dc2-4aa1-9c1b-8c5771454988', 2, 'Hay elefantes que se pueden ver y una prohibición de tomar fotos: eso describe un zoológico. En una playa no hay elefantes, y un parque común tampoco los exhibe ni regula las fotos.');

