insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('8d9e33ad-6785-4dba-a165-0b05c9f2c920', 2, 'El aviso habla de un pupitre («desk») y del final de la jornada escolar: eso ocurre en el salón de clase. En un baño o un pasillo no hay pupitres que limpiar.');

