insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('27182f58-759d-4d58-bc01-58fe70d9ef13', 2, 'El aviso anuncia un partido para esa misma noche, así que es una cartelera dirigida a una comunidad que ya está reunida: el colegio. Ojo con la trampa: la cancha es donde ocurre el partido, no donde se anuncia.');

