insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3f413201-465c-4835-919e-baef824352f3', 1, 'Prohibir que el público alimente a los animales solo hace falta donde hay animales en exhibición y visitantes cerca: el zoológico. En un jardín o una playa no hay animales bajo cuidado con una dieta controlada.');

