insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('cb9031c3-6828-403b-ad21-29d27241925f', 2, 'Naranjas, uvas y cocos son frutas con precio: es una oferta de una tienda de alimentos. La floristería vende flores y la tienda deportiva, implementos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '81447157-45a2-4d8b-b9e1-d45a338cb5cb', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-1-avisos'),
