  'f36d8de0-16a0-4150-b3ec-3b44201eb555', 'Parte 1 · Avisos y letreros',
  'Where can you see this notice?',
  array['at a zoo', 'at a garden', 'at a pet store'],
  'El animal que nombra el aviso te descarta dos opciones de una vez.', 'publicada', 'modelo', '6e5a44449c32d35c0e3e5a8f4304d52b';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('81447157-45a2-4d8b-b9e1-d45a338cb5cb', 0, 'Las jirafas no se tienen en jardines ni se venden como mascotas: viven en un zoológico, y allí se prohíbe que los visitantes las alimenten.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
