insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('37cfe2af-6696-4c2e-8ce4-9e11a9675832', 2, 'Lo que se protege son los «drawings», los dibujos, y los dibujos se hacen en la clase de pintura. En música y deportes no hay dibujos que fotografiar.');

