insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('32d036c1-2ac8-406d-86a7-abe1a57c0b62', 0, 'Es la calcomanía que llevan los camiones de empresa para que otros conductores reporten cómo maneja el chofer. Va en un vehículo grande y visible por detrás: el tren lo conduce un maquinista y no se adelanta, y una moto no tiene superficie para ese aviso.');

