insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('bb3f3b55-87c3-4819-8b79-ce803b7321b0', 2, 'Es el aviso de las sillas preferenciales del transporte público, donde los puestos son limitados y hay pasajeros de pie. Una bicicleta no tiene puestos que reservar.');

