insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6ba4c960-16b4-493b-996a-b62ca81f1b21', 2, 'Un «pie» es un pastel, y los pasteles se venden en la pastelería. Ni la juguetería ni la tienda de ropa venden comida.');

