insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f94016be-fe3a-49ad-b706-8dd73c08e6e9', 1, '«Crayons» son crayolas, el material propio de la clase de dibujo. En el salón de música se guardan instrumentos y en el de computadores, equipos.');

