insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f8d4b541-7b4e-4c51-a40d-91ce8b8845fd', 2, 'El jardín es el lugar que existe precisamente para cultivar flores, así que allí la prohibición protege lo que le da sentido al sitio. En la playa no hay flores, y el parque es un espacio mucho más general.');

