insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('454f2a21-b008-422c-8775-ae5f02bf06a0', 2, 'Es una norma dirigida a pasajeros, y el vehículo de esta lista que lleva pasajeros es el bus. En una bicicleta no hay dónde comer, y el camión lo ocupa el conductor, no un público al que se le fijen reglas.');

